(365697, 29312, 8956, '<td valign="top">Nice idea, but there is too much light at the sand and in the air. Take attention and it will improve your shot.</td>', 'Nice idea, but there is too much light at the sand and in the air. Take attention and it will improve your shot.', '2003-07-24 02:50:03.000000', NULL, 1),
(365699, 29893, 8956, '<td valign="top">to me, it''s just a candid-shot. Dark and grainy. Sorry.</td>', 'to me, it''s just a candid-shot. Dark and grainy. Sorry.', '2003-07-24 02:51:44.000000', NULL, 1),
(365702, 29987, 8956, '<td valign="top">a little bit out of focus.</td>', 'a little bit out of focus.', '2003-07-24 02:57:30.000000', NULL, 1),
