(365753, 29650, 10428, '<td valign="top">nice</td>', 'nice', '2003-07-24 03:45:12.000000', NULL, 1),
(365754, 29690, 7151, '<td valign="top">By the title, a good subject for the challenge.  However, this picture has the problem that the architecture is masked or hidden by excessive shadow and darkness.  The composition feels a little random, and it''s a bit tilted.  Colors are really nice, and asice from some resizing jaggies, it seems fairly sharp.</td>', 'By the title, a good subject for the challenge.  However, this picture has the problem that the architecture is masked or hidden by excessive shadow and darkness.  The composition feels a little random, and it''s a bit tilted.  Colors are really nice, and asice from some resizing jaggies, it seems fairly sharp.', '2003-07-24 03:45:18.000000', NULL, 1),
(365757, 29620, 10428, '<td valign="top">The Red Book!!!</td>', 'The Red Book!!!', '2003-07-24 03:45:50.000000', NULL, 1),
(365759, 30092, 10428, '<td valign="top">.....blurry, etc......good idea, shot could use some work</td>', '.....blurry, etc......good idea, shot could use some work', '2003-07-24 03:46:11.000000', NULL, 1),
