(367732, 29692, 1644, '<td valign="top">Bad trend, but a trend all the same. Good shot, no distracting background.</td>', 'Bad trend, but a trend all the same. Good shot, no distracting background.', '2003-07-27 13:00:36.000000', NULL, 1),
(367738, 30053, 1644, '<td valign="top">Good choice of trend. The picture really conveys a feeling, to me anyway.</td>', 'Good choice of trend. The picture really conveys a feeling, to me anyway.', '2003-07-27 13:22:00.000000', NULL, 1),
(367739, 30068, 1644, '<td valign="top">I just love the colors in this photograph. I like that it''s so simple, too.</td>', 'I just love the colors in this photograph. I like that it''s so simple, too.', '2003-07-27 13:28:04.000000', NULL, 1),
(367740, 29489, 1644, '<td valign="top">Now you are a person who is paying attention to their surroundings. However did you find such a great photo? I really like this one.</td>', 'Now you are a person who is paying attention to their surroundings. However did you find such a great photo? I really like this one.', '2003-07-27 13:31:13.000000', NULL, 1),
(367741, 29592, 1644, '<td valign="top">Poor thing, it looks stuffed. I really want to see the details of how you took this pic. I like that you are hiding, but that one branch is really annoying the way it covers his eye part way. If he is real, you''re a crazy person to be that close!</td>', 'Poor thing, it looks stuffed. I really want to see the details of how you took this pic. I like that you are hiding, but that one branch is really annoying the way it covers his eye part way. If he is real, you''re a crazy person to be that close!', '2003-07-27 13:38:15.000000', NULL, 1),
